mod cli;
mod config;
mod logger;
mod prompt;
mod git;
mod json;

use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use cli::EurekaOptions;
use config::Config;
use logger::{init_logger, log_debug, log_error};

fn main() {
    let argv: Vec<String> = env::args().collect();
    let opts = match cli::parse(&argv) {
        Ok(Some(o)) => o,
        Ok(None) => return,
        Err(code) => std::process::exit(code),
    };

    init_logger();

    log_debug(&format!("Running with options: {:?}", opts));

    if let Err(e) = run(&opts) {
        log_error(&e);
    }
}

fn run(opts: &EurekaOptions) -> Result<(), String> {
    if opts.clear_config {
        return clear_config();
    }

    if opts.view {
        return view_ideas();
    }

    // Normal operation: capture idea
    let config = load_or_init_config()?;
    let repo_path = config.repo;

    // Check that the repo exists and is a git repo (using libgit2-like errors)
    git::ensure_repo(&repo_path)?;

    // Prompt for idea summary
    let summary = prompt::ask_summary().map_err(|e| format!("{}", e))?;

    // Open editor on README.md (ignore error for now but capture it)
    let readme = repo_path.join("README.md");
    let editor_err = match open_editor(&readme) {
        Ok(()) => None,
        Err(e) => Some(e),
    };

    // Add, commit, push
    println!("Adding and committing your new idea to main..");
    git::add_and_commit(&repo_path, "README.md", &summary)?;
    println!("Added and committed!");

    println!("Pushing your new idea..");
    git::push(&repo_path)?;
    println!("Pushed!");

    if let Some(e) = editor_err {
        return Err(e);
    }

    Ok(())
}

fn config_dir() -> PathBuf {
    if let Some(xdg) = env::var_os("XDG_CONFIG_HOME") {
        PathBuf::from(xdg).join("eureka")
    } else if let Some(home) = env::var_os("HOME") {
        PathBuf::from(home).join(".config").join("eureka")
    } else {
        PathBuf::from(".config/eureka")
    }
}

fn config_path() -> PathBuf {
    config_dir().join("config.json")
}

fn clear_config() -> Result<(), String> {
    let path = config_path();
    fs::remove_file(&path).map_err(|e| format!("{}", e))?;
    log_debug("Cleared config");
    Ok(())
}

fn view_ideas() -> Result<(), String> {
    let cfg = Config::load(&config_path()).map_err(|e| format!("{}", e))?;
    let readme = cfg.repo.join("README.md");
    let pager = env::var("PAGER").ok().filter(|s| !s.is_empty()).unwrap_or_else(|| "less".to_string());
    let status = Command::new(&pager)
        .arg(&readme)
        .status()
        .map_err(|e| format!("{}", e))?;
    let _ = status;
    Ok(())
}

fn load_or_init_config() -> Result<Config, String> {
    let path = config_path();
    if !path.exists() {
        log_debug("Config is missing");
        // Ensure config dir exists
        let dir = config_dir();
        if !dir.exists() {
            fs::create_dir_all(&dir).map_err(|e| format!("{}", e))?;
            log_debug("Created config dir");
        }
        // Show banner and prompt for repo path
        show_first_time_banner();
        let path_str = prompt::ask_repo_path().map_err(|e| format!("{}", e))?;
        let cfg = Config { repo: PathBuf::from(path_str) };
        cfg.save(&path).map_err(|e| format!("{}", e))?;
        log_debug("Setup repo path successfully");
        println!("First time setup complete. Happy ideation!");
        // Return - don't enter main flow? Actually the observed behavior is: exit after setup
        std::process::exit(0);
    }
    Config::load(&path).map_err(|e| format!("{}", e))
}

fn show_first_time_banner() {
    print!("\x1b[0m\x1b[33m");
    println!("############################################################");
    println!("####                  First Time Setup                  ####");
    println!("############################################################");
    println!();
    println!("This tool requires you to have a repository with a README.md");
    println!("in the root folder. The markdown file is where your ideas");
    println!("will be stored.");
    println!();
    println!("Once first time setup has completed, simply run Eureka again");
    println!("to begin writing down ideas.");
    println!("        ");
    print!("\x1b[0m");
    io::stdout().flush().ok();
}

fn open_editor(file: &Path) -> Result<(), String> {
    let editor = env::var("EDITOR").unwrap_or_default();
    if editor.is_empty() {
        return Err("cannot find binary path".to_string());
    }
    // Use `which` logic: check PATH for the editor binary
    // If EDITOR has a path separator, we try direct spawn
    let status = Command::new(&editor)
        .arg(file)
        .status()
        .map_err(|e| format!("{}", e))?;
    // Ignore exit code
    let _ = status;
    Ok(())
}
EOF

