cat > /workspace/src/cli.rs <<'EOF'
use std::path::Path;

#[derive(Debug)]
pub struct EurekaOptions {
    pub clear_config: bool,
    pub view: bool,
}

const ABOUT: &str = "Input and store your ideas without leaving the terminal";
const VERSION: &str = "eureka 2.0.0";

fn bin_name(argv0: &str) -> String {
    Path::new(argv0)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("eureka")
        .to_string()
}

fn print_usage(name: &str, out: &mut impl std::io::Write) {
    writeln!(out, "{}", ABOUT).ok();
    writeln!(out).ok();
    writeln!(out, "Usage: {} [OPTIONS]", name).ok();
    writeln!(out).ok();
    writeln!(out, "Options:").ok();
    writeln!(
        out,
        "      --clear-config  Clear your stored configuration"
    )
    .ok();
    writeln!(
        out,
        "  -v, --view          View ideas with your $PAGER env variable. If unset use less"
    )
    .ok();
    writeln!(out, "  -h, --help          Print help").ok();
    writeln!(out, "  -V, --version       Print version").ok();
}

fn print_usage_short(name: &str, out: &mut impl std::io::Write) {
    writeln!(out, "Usage: {} [OPTIONS]", name).ok();
    writeln!(out).ok();
    writeln!(out, "For more information, try '--help'.").ok();
}

/// Returns:
/// Ok(Some(opts)) if should continue
/// Ok(None) if should exit 0 (help/version printed)
/// Err(code) if should exit with that code after printing error
pub fn parse(argv: &[String]) -> Result<Option<EurekaOptions>, i32> {
    let name = if argv.is_empty() {
        "eureka".to_string()
    } else {
        bin_name(&argv[0])
    };

    let mut clear_config = false;
    let mut view = false;

    let mut i = 1usize;
    while i < argv.len() {
        let arg = &argv[i];
        match arg.as_str() {
            "--clear-config" => {
                clear_config = true;
            }
            "-v" | "--view" => {
                view = true;
            }
            "-h" | "--help" => {
                let stdout = std::io::stdout();
                let mut out = stdout.lock();
                print_usage(&name, &mut out);
                return Ok(None);
            }
            "-V" | "--version" => {
                println!("{}", VERSION);
                return Ok(None);
            }
            other => {
                let stderr = std::io::stderr();
                let mut err = stderr.lock();
                writeln!(err, "error: unexpected argument '{}' found", other).ok();
                writeln!(err).ok();
                print_usage_short(&name, &mut err);
                return Err(2);
            }
        }
        i += 1;
    }

    Ok(Some(EurekaOptions { clear_config, view }))
}
