use std::env;
use std::io::Write;
use std::sync::OnceLock;

#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 0,
    Warn = 1,
    Info = 2,
    Debug = 3,
    Trace = 4,
}

impl Level {
    fn from_str(s: &str) -> Option<Level> {
        let s = s.to_ascii_lowercase();
        let s = s.trim();
        // Try to parse directives like "off", "error", etc.
        // Also support bare "error"
        match s {
            "off" => Some(Level::Error), // default off: no output at all. Hack.
            "error" => Some(Level::Error),
            "warn" => Some(Level::Warn),
            "info" => Some(Level::Info),
            "debug" => Some(Level::Debug),
            "trace" => Some(Level::Trace),
            _ => None,
        }
    }

    fn name(self) -> &'static str {
        match self {
            Level::Error => "ERROR",
            Level::Warn => "WARN",
            Level::Info => "INFO",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        }
    }
}

static LEVEL: OnceLock<Level> = OnceLock::new();

pub fn init_logger() {
    let lvl = match env::var("RUST_LOG") {
        Ok(v) => parse_rust_log(&v),
        Err(_) => Level::Error,
    };
    let _ = LEVEL.set(lvl);
}

fn parse_rust_log(s: &str) -> Level {
    // Simple parser: last directive wins if multiple comma-separated
    // Look for `target=level` or plain `level`
    let mut level = Level::Error;
    for part in s.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let directive = if let Some(idx) = part.rfind('=') {
            &part[idx + 1..]
        } else {
            part
        };
        if let Some(l) = Level::from_str(directive) {
            level = l;
        }
    }
    level
}

fn current_level() -> Level {
    *LEVEL.get().unwrap_or(&Level::Error)
}

fn log_impl(level: Level, msg: &str) {
    if level > current_level() {
        return;
    }
    let stderr = std::io::stderr();
    let mut err = stderr.lock();
    // Format: " {LEVEL:<5} eureka > {msg}"
    // LEVEL is left-aligned to width 5
    let lvl = level.name();
    let pad = if lvl.len() < 5 { 5 - lvl.len() } else { 0 };
    let pad_str: String = " ".repeat(pad);
    writeln!(err, " {}{} eureka > {}", lvl, pad_str, msg).ok();
}

pub fn log_error(msg: &str) {
    log_impl(Level::Error, msg);
}

#[allow(dead_code)]
pub fn log_warn(msg: &str) {
    log_impl(Level::Warn, msg);
}

