// Minimal JSON parser/serializer for our Config struct.
// Supports reading/writing a simple object of string fields.

use std::fmt;

#[derive(Debug)]
pub struct JsonError {
    pub msg: String,
}

impl fmt::Display for JsonError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.msg)
    }
}

// Parse and find the value of a given string key in a JSON object.
// Returns:
// Ok(None) if key not found (object is valid JSON)
// Ok(Some(value)) if key was found (value is the string value)
// Err(msg) if parse error
// Position-aware error messages like "expected ident at line 1 column 2"
// or "missing field `repo` at line N column M"
// or "invalid type: integer `123`, expected path string at line 1 column 12"

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
    line: usize,
    col: usize,
}

#[derive(Debug, Clone)]
enum Value {
    String(String),
    Number(String),
    Bool(bool),
    Null,
    Array,
    Object,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { bytes: s.as_bytes(), pos: 0, line: 1, col: 1 }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let b = self.peek()?;
        self.pos += 1;
        if b == b'\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        Some(b)
    }

    fn skip_ws(&mut self) {
        while let Some(b) = self.peek() {
            if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn error_here(&self, msg: String) -> JsonError {
        JsonError {
            msg: format!("{} at line {} column {}", msg, self.line, self.col),
        }
    }

    fn parse_string(&mut self) -> Result<String, JsonError> {
        if self.peek() != Some(b'"') {
            return Err(self.error_here("expected string".into()));
        }
        self.advance(); // consume opening "
        let mut s = String::new();
        while let Some(b) = self.peek() {
            if b == b'"' {
                self.advance();
                return Ok(s);
            }
            if b == b'\\' {
                self.advance();
                let esc = self.peek().ok_or_else(|| self.error_here("unterminated escape".into()))?;
                self.advance();
                match esc {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'n' => s.push('\n'),
                    b't' => s.push('\t'),
                    b'r' => s.push('\r'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0c'),
                    b'u' => {
                        // parse 4 hex digits
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let h = self.peek().ok_or_else(|| self.error_here("expected hex".into()))?;
                            self.advance();
                            let d = match h {
                                b'0'..=b'9' => (h - b'0') as u32,
                                b'a'..=b'f' => (h - b'a' + 10) as u32,
                                b'A'..=b'F' => (h - b'A' + 10) as u32,
                                _ => return Err(self.error_here("invalid hex".into())),
                            };
                            code = code * 16 + d;
                        }
                        if let Some(c) = char::from_u32(code) {
                            s.push(c);
                        }
                    }
                    _ => return Err(self.error_here("invalid escape".into())),
                }
            } else {
                self.advance();
                s.push(b as char); // ASCII only simple handling; for UTF-8 bytes, this is wrong but we push raw
            }
        }
        Err(self.error_here("unterminated string".into()))
