// Returns:
// Ok(None) if key not found (object is valid JSON)
// Ok(Some(value)) if key was found (value is the string value)
// Err(msg) if parse error
// Position-aware error messages like "expected ident at line 1 column 2"
// or "missing field `repo` at line N column M"
// or "invalid type: integer `123`, expected path string at line 1 column 12"

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
    line: usize,
    col: usize,
}

#[derive(Debug, Clone)]
enum Value {
    String(String),
    Number(String),
    Bool(bool),
    Null,
    Array,
    Object,
}

