use std::fs;
use std::path::{Path, PathBuf};

use crate::json;

#[derive(Debug, Clone)]
pub struct Config {
    pub repo: PathBuf,
}

#[derive(Debug)]
pub enum ConfigError {
    Io(std::io::Error),
    Json(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "{}", e),
            ConfigError::Json(s) => write!(f, "{}", s),
        }
    }
}

impl From<std::io::Error> for ConfigError {
    fn from(e: std::io::Error) -> Self {
        ConfigError::Io(e)
    }
}

impl Config {
    pub fn load(path: &Path) -> Result<Self, ConfigError> {
        let data = fs::read_to_string(path)?;
        let repo = json::extract_repo(&data).map_err(|e| ConfigError::Json(e.msg))?;
        Ok(Config { repo: PathBuf::from(repo) })
    }

    pub fn save(&self, path: &Path) -> Result<(), ConfigError> {
        let repo_str = self.repo.to_string_lossy();
        let data = json::serialize_config(&repo_str);
        fs::write(path, data)?;
        Ok(())
    }
}
