use std::io::{self, BufRead, Write};

/// Prompt for the initial idea repo path (used in first-time setup).
/// Returns the validated absolute path (trimmed). Re-prompts on empty or non-absolute.
pub fn ask_repo_path() -> io::Result<String> {
    loop {
        // Print prompt: bold green label + "> "
        {
            let stdout = io::stdout();
            let mut out = stdout.lock();
            write!(out, "\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ")?;
            out.flush()?;
        }
        let line = read_line()?;
        let trimmed = line.trim().to_string();
        if trimmed.is_empty() {
            // silent re-prompt
            continue;
        }
        if !trimmed.starts_with('/') {
            let stdout = io::stdout();
            let mut out = stdout.lock();
            write!(out, "\x1b[0m\x1b[31mPath must be absolute\n")?;
            out.flush()?;
            continue;
        }
        return Ok(trimmed);
    }
}

/// Prompt for idea summary. Re-prompts on empty. Returns trimmed-ish or raw?
/// Observed: " " also re-prompts, so it trims whitespace and checks for empty.
pub fn ask_summary() -> io::Result<String> {
    loop {
        {
            let stdout = io::stdout();
            let mut out = stdout.lock();
            write!(out, "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ")?;
            out.flush()?;
        }
        let line = read_line()?;
        let trimmed = line.trim().to_string();
        if trimmed.is_empty() {
            continue;
        }
        return Ok(trimmed);
    }
}

fn read_line() -> io::Result<String> {
    let stdin = io::stdin();
    let mut s = String::new();
    let n = stdin.lock().read_line(&mut s)?;
    if n == 0 {
        // EOF; return empty which will re-prompt forever. To prevent infinite loop, propagate error.
        return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "EOF"));
    }
    // Strip trailing newline/CR
    if s.ends_with('\n') {
        s.pop();
        if s.ends_with('\r') {
            s.pop();
        }
    }
    Ok(s)
}
