// Git operations - we mimic libgit2 error messages where the original tool uses libgit2.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Checks that the repo path exists and is a git repository.
/// Matches libgit2 error formats:
/// - "failed to resolve path '{path}': No such file or directory; class=Os (2); code=NotFound (-3)"
/// - "could not find repository from '{path}'; class=Repository (6); code=NotFound (-3)"
pub fn ensure_repo(path: &Path) -> Result<(), String> {
    // Try to resolve path
    if !path.exists() {
        return Err(format!(
            "failed to resolve path '{}': No such file or directory; class=Os (2); code=NotFound (-3)",
            path.display()
        ));
    }
    // Check for .git directory or file - libgit2 searches parent dirs too; let's check presence of .git here
    if !path.join(".git").exists() {
        return Err(format!(
            "could not find repository from '{}'; class=Repository (6); code=NotFound (-3)",
            path.display()
        ));
    }
    Ok(())
}

/// Gets the current HEAD commit sha (via git CLI).
/// If HEAD is unborn, returns error matching libgit2 format.
fn head_ref(path: &Path) -> Result<String, String> {
    // Get the symbolic HEAD ref name
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["symbolic-ref", "HEAD"])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        return Err("HEAD is not a symbolic ref".to_string());
    }
    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
    Ok(s)
}

fn rev_parse(path: &Path, r: &str) -> Result<Option<String>, String> {
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["rev-parse", "--verify", r])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        return Ok(None);
    }
    Ok(Some(String::from_utf8_lossy(&out.stdout).trim().to_string()))
}

/// Add README.md to index and commit with given message. Commits to refs/heads/main
/// and updates HEAD to main.
pub fn add_and_commit(path: &Path, file: &str, message: &str) -> Result<(), String> {
    // Resolve HEAD - if unborn, return error in libgit2 format
    let head = head_ref(path)?;
    let head_rev = rev_parse(path, "HEAD")?;
    if head_rev.is_none() {
        return Err(format!(
            "reference '{}' not found; class=Reference (4); code=UnbornBranch (-9)",
            head
        ));
    }
    let parent_sha = head_rev.unwrap();

    // Check user.name and user.email (libgit2 would also check this)
    let name = get_config(path, "user.name")
        .map_err(|_| "config value 'user.name' was not found; class=Config (7); code=NotFound (-3)".to_string())?;
    let email = get_config(path, "user.email")
        .map_err(|_| "config value 'user.email' was not found; class=Config (7); code=NotFound (-3)".to_string())?;

    // git add
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["add", file])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(err);
    }

    // git write-tree (produce the tree for current index)
    let tree_out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["write-tree"])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !tree_out.status.success() {
        let err = String::from_utf8_lossy(&tree_out.stderr).trim().to_string();
        return Err(err);
    }
    let tree_sha = String::from_utf8_lossy(&tree_out.stdout).trim().to_string();

    // git commit-tree with parent and message
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["commit-tree", &tree_sha, "-p", &parent_sha, "-m", message])
        .env("GIT_AUTHOR_NAME", &name)
        .env("GIT_AUTHOR_EMAIL", &email)
        .env("GIT_COMMITTER_NAME", &name)
        .env("GIT_COMMITTER_EMAIL", &email)
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(err);
    }
    let new_sha = String::from_utf8_lossy(&out.stdout).trim().to_string();

    // Update refs/heads/main
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["update-ref", "refs/heads/main", &new_sha])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(err);
    }

    // Set HEAD to refs/heads/main
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["symbolic-ref", "HEAD", "refs/heads/main"])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(err);
    }

    Ok(())
}

fn get_config(path: &Path, key: &str) -> Result<String, String> {
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["config", "--get", key])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        return Err(format!("no value for {}", key));
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// Push to origin.
pub fn push(path: &Path) -> Result<(), String> {
    // Check that origin remote exists
    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["config", "--get", "remote.origin.url"])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        return Err("remote 'origin' does not exist; class=Config (7); code=NotFound (-3)".to_string());
    }
    let url = String::from_utf8_lossy(&out.stdout).trim().to_string();

    // Try to push - libgit2 would check URL scheme
    // For local file paths without file:// prefix, libgit2 says "unsupported URL protocol; class=Net (12)"
    // For absolute paths, we can let `git` attempt the push (matches libgit2 success)
    // Detect if it looks like a URL libgit2 would accept:
    //   file://...  http://  https://  ssh://  git://  user@host:path
    // Else "unsupported URL protocol"
    if !is_supported_url(&url) {
        return Err("unsupported URL protocol; class=Net (12)".to_string());
    }

    let out = Command::new("git")
        .args(["-C"])
        .arg(path)
        .args(["push", "origin", "HEAD:refs/heads/main"])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(err);
    }
    Ok(())
}

fn is_supported_url(url: &str) -> bool {
    if url.starts_with("file://") || url.starts_with("http://") || url.starts_with("https://") || url.starts_with("ssh://") || url.starts_with("git://") {
        return true;
    }
    // SCP-like: user@host:path
    if url.contains('@') && url.contains(':') {
        return true;
    }
    // Absolute filesystem paths are treated as local - libgit2 usually supports these
    if url.starts_with('/') {
        // A bare path like /nonexistent/remote - libgit2 says "unsupported URL protocol"
        // unless wrapped in file://? Actually based on my test, /nonexistent/remote gave "unsupported URL protocol"
        return false;
    }
    false
}

