    }

    let out = git_cmd(path)
        .args(["push", "origin", "HEAD:refs/heads/main"])
        .output()
        .map_err(|e| format!("{}", e))?;
    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(stderr);
    }
    Ok(())
}

fn is_local_path_url(url: &str) -> bool {
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("ssh://") || url.starts_with("git://") {
        return false;
    }
    if url.starts_with("file://") {
        return true;
    }
    // SCP-like user@host:path
    if url.contains('@') && url.contains(':') && !url.starts_with('/') {
        return false;
    }
    // Absolute path
    url.starts_with('/')
}

fn local_path(url: &str) -> String {
    if let Some(rest) = url.strip_prefix("file://") {
        rest.to_string()
    } else {
        url.to_string()
    }
}
