            // Actually serde reports position "past" the last character. If last char was newline,
            // line has already advanced. If not, it uses current line.
            // From observations: empty "" -> "line 2 column 0", "{" (no newline) -> "line 2 column 0"
            // So it's always "next line, column 0" at EOF.
            ParseError {
                msg: format!("{} at line {} column 0", msg, self.line + eof_line_offset(self.bytes)),
            }
        } else {
            ParseError {
                msg: format!("{} at line {} column {}", msg, self.line, self.col),
            }
        }
    }

    fn err_last(&self, msg: String) -> ParseError {
        ParseError {
            msg: format!("{} at line {} column {}", msg, self.last_line, self.last_col),
        }
    }

    // Parse a string starting at current `"`. Advances through closing `"`.
    // On success returns the string content and the column of the closing quote.
    fn parse_string(&mut self) -> Result<String, ParseError> {
        // Expect opening "
        if self.peek() != Some(b'"') {
            return Err(self.err_next("expected value".into()));
