            self.parse_value()?;
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.advance(); self.skip_ws(); }
                Some(b']') => { self.advance(); return Ok(()); }
                None => return Err(self.err_next("EOF while parsing a list".into())),
                _ => return Err(self.err_next("expected `,` or `]`".into())),
            }
        }
    }

    fn skip_object(&mut self) -> Result<(), ParseError> {
        self.advance(); // consume {
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.advance();
            return Ok(());
        }
        loop {
            self.skip_ws();
            if self.peek().is_none() {
                return Err(self.err_next("EOF while parsing an object".into()));
            }
            // parse key
            if self.peek() != Some(b'"') {
                return Err(self.err_next("key must be a string".into()));
            }
            let _ = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') {
                if self.peek().is_none() {
                    return Err(self.err_next("EOF while parsing an object".into()));
                }
                return Err(self.err_next("expected `:`".into()));
            }
            self.advance();
            self.parse_value()?;
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.advance(); self.skip_ws(); }
                Some(b'}') => { self.advance(); return Ok(()); }
                None => return Err(self.err_next("EOF while parsing an object".into())),
                _ => return Err(self.err_next("expected `,` or `}`".into())),
            }
        }
    }
}

fn eof_line_offset(bytes: &[u8]) -> usize {
    // If the file ended with a newline, the line counter has already advanced
    // past it. Return 0 so that "line N column 0" uses the current line.
    // If the file did NOT end with a newline, we need to add 1 to represent
    // the "next line".
    if bytes.last() == Some(&b'\n') {
        0
    } else {
        1
    }
}

pub fn extract_repo(s: &str) -> Result<String, ParseError> {
    let mut p = Parser::new(s);
    p.skip_ws();

    // Check for empty/EOF
    match p.peek() {
        None => return Err(p.err_next("EOF while parsing a value".into())),
        Some(b) => {
            // Top-level must be an object {, anything else is a top-level-type error
            match b {
                b'{' => {}
                b'"' => {
                    let val = p.parse_string()?;
                    let (vl, vc) = (p.last_line, p.last_col);
                    return Err(ParseError {
                        msg: format!(
                            "invalid type: string \"{}\", expected struct Config at line {} column {}",
                            val, vl, vc
                        ),
                    });
                }
                b't' | b'f' => {
                    let tok = if b == b't' { b"true" } else { b"false" };
                    p.parse_keyword(tok)?;
                    let s_val = std::str::from_utf8(tok).unwrap();
                    return Err(ParseError {
                        msg: format!(
                            "invalid type: boolean `{}`, expected struct Config at line {} column {}",
                            s_val, p.last_line, p.last_col
                        ),
                    });
                }
                b'n' => {
                    p.parse_keyword(b"null")?;
                    return Err(ParseError {
                        msg: format!(
                            "invalid type: null, expected struct Config at line {} column {}",
                            p.last_line, p.last_col
                        ),
                    });
                }
                b'0'..=b'9' | b'-' => {
                    let v = p.parse_number()?;
                    match v {
                        Value::Int(s) => return Err(ParseError {
                            msg: format!(
                                "invalid type: integer `{}`, expected struct Config at line {} column {}",
                                s, p.last_line, p.last_col
                            ),
                        }),
                        Value::Float(s) => return Err(ParseError {
                            msg: format!(
                                "invalid type: floating point `{}`, expected struct Config at line {} column {}",
                                s, p.last_line, p.last_col
                            ),
                        }),
                        _ => unreachable!(),
                    }
                }
                b'[' => {
                    // Array as struct: "invalid length N, expected struct Config with 1 element"
                    // We need to count array elements
                    let (count, end_col_line) = count_array_elements(&mut p)?;
                    let _ = end_col_line;
                    return Err(ParseError {
                        msg: format!(
                            "invalid length {}, expected struct Config with 1 element at line {} column {}",
                            count, p.last_line, p.last_col
                        ),
                    });
                }
                _ => {
                    return Err(p.err_next("expected ident".into()));
                }
            }
        }
    }

    // Parse the object
    p.advance(); // consume {
    p.skip_ws();

    let mut found_repo: Option<Value> = None;

    if p.peek() == Some(b'}') {
        p.advance();
    } else {
        loop {
            p.skip_ws();
            if p.peek().is_none() {
                return Err(p.err_next("EOF while parsing an object".into()));
            }
            if p.peek() != Some(b'"') {
                // key must be string - but first char was not "
                // For unexpected tokens, "expected ident" at... let me check
                return Err(p.err_next("key must be a string".into()));
            }
            let key = p.parse_string()?;
            p.skip_ws();
            if p.peek() != Some(b':') {
                if p.peek().is_none() {
                    return Err(p.err_next("EOF while parsing an object".into()));
                }
                return Err(p.err_next("expected `:`".into()));
            }
            p.advance();

            // Parse value; if it's the repo key, need to distinguish types
            p.skip_ws();
            let val_line = p.line;
            let val_col = p.col;
            let peek = match p.peek() {
                None => return Err(p.err_next("EOF while parsing a value".into())),
                Some(b) => b,
            };

            if key == "repo" {
                // We want a string; produce type errors for other types
                match peek {
                    b'"' => {
                        let s_val = p.parse_string()?;
                        found_repo = Some(Value::String(s_val));
                    }
                    b't' => {
                        p.parse_keyword(b"true")?;
                        return Err(ParseError {
                            msg: format!(
                                "invalid type: boolean `true`, expected path string at line {} column {}",
                                p.last_line, p.last_col
                            ),
                        });
                    }
                    b'f' => {
                        p.parse_keyword(b"false")?;
                        return Err(ParseError {
                            msg: format!(
                                "invalid type: boolean `false`, expected path string at line {} column {}",
                                p.last_line, p.last_col
                            ),
                        });
                    }
                    b'n' => {
                        p.parse_keyword(b"null")?;
                        return Err(ParseError {
                            msg: format!(
                                "invalid type: null, expected path string at line {} column {}",
                                p.last_line, p.last_col
                            ),
                        });
                    }
                    b'0'..=b'9' | b'-' => {
                        let v = p.parse_number()?;
                        match v {
                            Value::Int(s) => return Err(ParseError {
                                msg: format!(
                                    "invalid type: integer `{}`, expected path string at line {} column {}",
                                    s, p.last_line, p.last_col
                                ),
                            }),
                            Value::Float(s) => return Err(ParseError {
                                msg: format!(
                                    "invalid type: floating point `{}`, expected path string at line {} column {}",
                                    s, p.last_line, p.last_col
                                ),
                            }),
                            _ => unreachable!(),
                        }
                    }
                    b'[' => {
                        // For sequence, position is BEFORE [
                        let prev_col = if val_col > 1 { val_col - 1 } else { 1 };
                        let prev_line = val_line;
                        p.skip_array()?;
                        return Err(ParseError {
                            msg: format!(
                                "invalid type: sequence, expected path string at line {} column {}",
                                prev_line, prev_col
                            ),
                        });
                    }
                    b'{' => {
                        let prev_col = if val_col > 1 { val_col - 1 } else { 1 };
                        let prev_line = val_line;
                        p.skip_object()?;
                        return Err(ParseError {
                            msg: format!(
                                "invalid type: map, expected path string at line {} column {}",
                                prev_line, prev_col
                            ),
                        });
                    }
                    _ => return Err(p.err_next("expected value".into())),
                }
            } else {
                // Not repo key; skip value
                let _ = p.parse_value()?;
            }

            p.skip_ws();
            match p.peek() {
                Some(b',') => { p.advance(); p.skip_ws(); }
                Some(b'}') => { p.advance(); break; }
                None => return Err(p.err_next("EOF while parsing an object".into())),
                _ => return Err(p.err_next("expected `,` or `}`".into())),
            }
        }
    }

    // After object, check trailing characters
    p.skip_ws();
    if p.peek().is_some() {
        return Err(ParseError {
            msg: format!("trailing characters at line {} column {}", p.line, p.col),
        });
    }

    match found_repo {
        Some(Value::String(s)) => Ok(s),
        None => Err(ParseError {
            msg: format!("missing field `repo` at line {} column {}", p.last_line, p.last_col),
        }),
        _ => unreachable!(),
    }
}

fn count_array_elements(p: &mut Parser) -> Result<(usize, (usize, usize)), ParseError> {
    p.advance(); // consume [
    p.skip_ws();
    let mut n = 0;
    if p.peek() == Some(b']') {
        p.advance();
        return Ok((n, (p.last_line, p.last_col)));
    }
    loop {
        p.parse_value()?;
        n += 1;
        p.skip_ws();
        match p.peek() {
            Some(b',') => { p.advance(); p.skip_ws(); }
            Some(b']') => { p.advance(); return Ok((n, (p.last_line, p.last_col))); }
            None => return Err(p.err_next("EOF while parsing a list".into())),
            _ => return Err(p.err_next("expected `,` or `]`".into())),
        }
    }
}

pub fn serialize_config(repo: &str) -> String {
    let mut s = String::new();
    s.push_str("{\"repo\":");
    s.push('"');
    for c in repo.chars() {
        match c {
            '"' => s.push_str("\\\""),
            '\\' => s.push_str("\\\\"),
            '\n' => s.push_str("\\n"),
            '\r' => s.push_str("\\r"),
            '\t' => s.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                s.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => s.push(c),
        }
    }
    s.push('"');
    s.push('}');
    s
}
