// Minimal JSON parser that emits serde_json-compatible error messages.
// Supports extracting the "repo" field from a JSON object.

pub struct ParseError {
    pub msg: String,
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,      // current byte position
    line: usize,     // 1-based
    col: usize,      // 1-based col of NEXT byte to read
    last_line: usize,
    last_col: usize, // 1-based col of LAST consumed byte (0 if none)
}

#[derive(Debug, Clone)]
enum Value {
    String(String),
    Int(String),
    Float(String),
    Bool(bool),
    Null,
    Sequence,
    Map,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { bytes: s.as_bytes(), pos: 0, line: 1, col: 1, last_line: 1, last_col: 0 }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let b = self.peek()?;
        self.last_line = self.line;
        self.last_col = self.col;
        self.pos += 1;
        if b == b'\n' {
            self.line += 1;
            self.col = 1;
        } else {
            self.col += 1;
        }
        Some(b)
    }

    fn skip_ws(&mut self) {
        while let Some(b) = self.peek() {
            if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn err_next(&self, msg: String) -> ParseError {
        // Error at current (next-to-read) position. At EOF, serde reports
        // "at line N+1 column 0" (or line of last, but column advanced by 1)
        if self.pos >= self.bytes.len() {
            // EOF - serde reports line+1 col 0 when there was no trailing newline?
            // Actually serde reports position "past" the last character. If last char was newline,
            // line has already advanced. If not, it uses current line.
            // From observations: empty "" -> "line 2 column 0", "{" (no newline) -> "line 2 column 0"
            // So it's always "next line, column 0" at EOF.
            ParseError {
                msg: format!("{} at line {} column 0", msg, self.line + eof_line_offset(self.bytes)),
            }
        } else {
            ParseError {
                msg: format!("{} at line {} column {}", msg, self.line, self.col),
            }
        }
    }

    fn err_last(&self, msg: String) -> ParseError {
        ParseError {
            msg: format!("{} at line {} column {}", msg, self.last_line, self.last_col),
        }
    }

    // Parse a string starting at current `"`. Advances through closing `"`.
    // On success returns the string content and the column of the closing quote.
    fn parse_string(&mut self) -> Result<String, ParseError> {
        // Expect opening "
        if self.peek() != Some(b'"') {
            return Err(self.err_next("expected value".into()));
        }
        self.advance();
        let mut s = String::new();
        loop {
            match self.peek() {
                None => return Err(self.err_next("EOF while parsing a string".into())),
                Some(b) => {
                    if b < 0x20 {
                        // control char
                        // Report at current position (which is where the control char is being read)
                        // Observations: `"` (newline EOF) -> line 2 col 0 "control character"
                        // The newline advances line counter. After reading `\n`, position is line 2 col 1, but error is reported BEFORE advancing.
                        // Actually: `"\n` — `"` at line 1 col 1, advance (col 2). Then peek `\n` at line 1 col 2. Error: "control character ... at line 2 column 0".
                        // That's interesting. serde must advance past the newline then report at the new position col 0.
                        // Let me just special-case: advance past newline, then report at new position with col 0
                        // This matches "line 2 col 0" for a single "\n"
                        if b == b'\n' {
                            self.advance();
                            return Err(ParseError {
                                msg: format!(
                                    "control character (\\u0000-\\u001F) found while parsing a string at line {} column 0",
                                    self.line
                                ),
                            });
                        } else {
                            return Err(self.err_next(
                                "control character (\\u0000-\\u001F) found while parsing a string".into()
                            ));
                        }
                    }
                    if b == b'"' {
                        self.advance();
                        return Ok(s);
                    }
                    if b == b'\\' {
                        self.advance();
                        let esc = self.peek().ok_or_else(|| self.err_next("EOF while parsing a string".into()))?;
                        self.advance();
                        match esc {
                            b'"' => s.push('"'),
                            b'\\' => s.push('\\'),
                            b'/' => s.push('/'),
                            b'n' => s.push('\n'),
                            b't' => s.push('\t'),
                            b'r' => s.push('\r'),
                            b'b' => s.push('\x08'),
                            b'f' => s.push('\x0c'),
                            b'u' => {
                                let mut code: u32 = 0;
                                for _ in 0..4 {
                                    let h = self.peek().ok_or_else(|| self.err_next("expected hex".into()))?;
                                    self.advance();
                                    let d = match h {
                                        b'0'..=b'9' => (h - b'0') as u32,
                                        b'a'..=b'f' => (h - b'a' + 10) as u32,
                                        b'A'..=b'F' => (h - b'A' + 10) as u32,
                                        _ => return Err(self.err_next("invalid hex".into())),
                                    };
                                    code = code * 16 + d;
                                }
                                if let Some(c) = char::from_u32(code) {
                                    s.push(c);
                                }
                            }
                            _ => return Err(self.err_next("invalid escape".into())),
                        }
                    } else {
                        // Consume byte. If multi-byte UTF-8, collect all bytes
                        self.advance();
                        // push as char - handle as ASCII for now; multi-byte: collect additional bytes
                        if b < 0x80 {
                            s.push(b as char);
                        } else {
                            // gather UTF-8 sequence
                            let nbytes = if b & 0xE0 == 0xC0 { 2 }
                                else if b & 0xF0 == 0xE0 { 3 }
                                else if b & 0xF8 == 0xF0 { 4 }
                                else { 1 };
                            let mut buf: Vec<u8> = vec![b];
                            for _ in 1..nbytes {
                                if let Some(nb) = self.peek() {
                                    self.advance();
                                    buf.push(nb);
                                } else {
                                    break;
                                }
                            }
                            if let Ok(text) = std::str::from_utf8(&buf) {
                                s.push_str(text);
                            }
                        }
                    }
                }
            }
        }
    }

    fn parse_keyword(&mut self, kw: &[u8]) -> Result<(), ParseError> {
        // already saw first char (peek matches kw[0])
        for &c in kw {
            match self.peek() {
                Some(b) if b == c => { self.advance(); }
                _ => return Err(self.err_next("expected ident".into())),
            }
        }
        Ok(())
    }

    fn parse_number(&mut self) -> Result<Value, ParseError> {
        let mut s = String::new();
        let mut is_float = false;
        while let Some(b) = self.peek() {
            match b {
                b'0'..=b'9' | b'-' | b'+' => { s.push(b as char); self.advance(); }
                b'.' | b'e' | b'E' => { is_float = true; s.push(b as char); self.advance(); }
                _ => break,
            }
        }
        if is_float {
            Ok(Value::Float(s))
        } else {
            Ok(Value::Int(s))
        }
    }

    // Parse a value, skip it (don't return content except for types).
    // Returns (value_descriptor, last_line, last_col)
    fn parse_value(&mut self) -> Result<(Value, usize, usize), ParseError> {
        self.skip_ws();
        let start_line = self.line;
        let start_col = self.col;
        let b = match self.peek() {
            None => return Err(self.err_next("EOF while parsing a value".into())),
            Some(b) => b,
        };
        match b {
            b'"' => {
                let s = self.parse_string()?;
                Ok((Value::String(s), self.last_line, self.last_col))
            }
            b't' => {
                self.parse_keyword(b"true")?;
                Ok((Value::Bool(true), self.last_line, self.last_col))
            }
            b'f' => {
                self.parse_keyword(b"false")?;
                Ok((Value::Bool(false), self.last_line, self.last_col))
            }
            b'n' => {
                self.parse_keyword(b"null")?;
                Ok((Value::Null, self.last_line, self.last_col))
            }
            b'[' => {
                // Report col for sequences is BEFORE the [. i.e., col just before.
                // From observation: `{"repo": [1,2,3]}` -> col 9 (the space before [)
                // So col before [ = start_col - 1. But if start_col is 1, there's no "before". Hmm.
                // Actually I think it's simpler: serde reports at position BEFORE the `[`.
                // start_col is col of `[`. Col before = start_col - 1. But in 1-based, "col 9" = position of space.
                // For `[]` at top, col 2 (the `]`). start_col = 1 (at `[`). So "after parsing []" reports col 2 (last_col).
                let prev_line = start_line;
                let prev_col = if start_col > 1 { start_col - 1 } else { 1 };
                self.skip_array()?;
                Ok((Value::Sequence, prev_line, prev_col))
            }
            b'{' => {
                self.skip_object()?;
                Ok((Value::Map, self.last_line, self.last_col))
            }
            b'0'..=b'9' | b'-' => {
                let v = self.parse_number()?;
                Ok((v, self.last_line, self.last_col))
            }
            _ => Err(self.err_next("expected value".into())),
        }
    }

    fn skip_array(&mut self) -> Result<(), ParseError> {
        self.advance(); // consume [
        self.skip_ws();
        if self.peek() == Some(b']') {
            self.advance();
            return Ok(());
        }
        loop {
            if self.peek().is_none() {
                return Err(self.err_next("EOF while parsing a list".into()));
            }
            self.parse_value()?;
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.advance(); self.skip_ws(); }
                Some(b']') => { self.advance(); return Ok(()); }
                None => return Err(self.err_next("EOF while parsing a list".into())),
                _ => return Err(self.err_next("expected `,` or `]`".into())),
            }
        }
    }

    fn skip_object(&mut self) -> Result<(), ParseError> {
        self.advance(); // consume {
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.advance();
            return Ok(());
        }
        loop {
            self.skip_ws();
            if self.peek().is_none() {
                return Err(self.err_next("EOF while parsing an object".into()));
            }
            // parse key
            if self.peek() != Some(b'"') {
                return Err(self.err_next("key must be a string".into()));
            }
            let _ = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') {
                if self.peek().is_none() {
                    return Err(self.err_next("EOF while parsing an object".into()));
                }
                return Err(self.err_next("expected `:`".into()));
            }
            self.advance();
            self.parse_value()?;
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.advance(); self.skip_ws(); }
                Some(b'}') => { self.advance(); return Ok(()); }
                None => return Err(self.err_next("EOF while parsing an object".into())),
                _ => return Err(self.err_next("expected `,` or `}`".into())),
            }
        }
    }
}

fn eof_line_offset(bytes: &[u8]) -> usize {
